/* Intermediate 2 · ShopKaro DNS decisions, cache budgets and serving-state repair. */
(function () {
  const N=AG.aws.n, HC='00000000-0000-4000-8000-000000000001';
  const ALB='shop-alb.sim.ap-south-1.elb.amazonaws.com', ALB_ZONE='ZP97RAFLXTNZK';
  const R=(name,extra,ip,ttl=60)=>({Name:name+'.shopkaro.in.',Type:'A',TTL:ttl,ResourceRecords:[{Value:ip}],...extra});
  const weighted=()=>[R('checkout',{SetIdentifier:'v1',Weight:90},'203.0.113.11'),R('checkout',{SetIdentifier:'v2',Weight:10},'203.0.113.12')];
  const failover=()=>[R('status',{SetIdentifier:'primary',Failover:'PRIMARY',HealthCheckId:HC},'203.0.113.10'),R('status',{SetIdentifier:'maintenance',Failover:'SECONDARY'},'203.0.113.20')];
  const apex=()=>({Name:'shopkaro.in.',Type:'A',AliasTarget:{DNSName:ALB,HostedZoneId:ALB_ZONE,EvaluateTargetHealth:true}});
  const config=()=>({Type:'HTTP',IPAddress:'203.0.113.10',Port:80,ResourcePath:'/ready',RequestInterval:30,FailureThreshold:3});
  const batch=records=>({Changes:records.map(r=>({Action:'UPSERT',ResourceRecordSet:r}))});
  const file=value=>({content:JSON.stringify(value,null,2)});
  function seed(){return {region:'ap-south-1',elbs:[{id:'alb-shop',name:'shop-alb',type:'application',scheme:'internet-facing',dns:ALB,canonicalHostedZoneId:ALB_ZONE}],hostedZones:[{id:'ZSHOP',name:'shopkaro.in.',callerReference:'shop-original',records:[{Name:'shopkaro.in.',Type:'NS',TTL:172800,ResourceRecords:[{Value:'ns-1.sim.invalid.'},{Value:'ns-2.sim.invalid.'}]},{Name:'shopkaro.in.',Type:'SOA',TTL:900,ResourceRecords:[{Value:'ns-1.sim.invalid. hostmaster.sim.invalid. 1 7200 900 1209600 86400'}]},...weighted().map(r=>({...r,Weight:50})),...failover().map(r=>{const x={...r,TTL:3600};delete x.HealthCheckId;return x;})]}],healthChecks:[],dnsChanges:[],dnsAliases:[{dnsName:ALB,hostedZoneId:ALB_ZONE,healthy:true,addresses:['203.0.113.100']}],dnsHealthFixtures:{'203.0.113.10':false,'203.0.113.20':true},buckets:[{name:'shop-assets',public:false,encryption:true,objects:[]}]};}
  const zone=s=>(s.account.hostedZones||[]).find(z=>z.id==='ZSHOP');
  function eq(a,b){if(a===b)return true;if(!a||!b||typeof a!=='object'||typeof b!=='object')return false;const ak=Object.keys(a).sort(),bk=Object.keys(b).sort();return ak.length===bk.length&&ak.every((k,i)=>k===bk[i]&&eq(a[k],b[k]));}
  function contains(actual,expected){return expected.every(e=>actual.some(r=>r.Name===e.Name&&r.Type===e.Type&&r.SetIdentifier===e.SetIdentifier&&r.TTL===e.TTL&&r.Weight===e.Weight&&r.Failover===e.Failover&&r.HealthCheckId===e.HealthCheckId&&eq(r.ResourceRecords,e.ResourceRecords)&&eq(r.AliasTarget,e.AliasTarget)));}
  const served=s=>{const z=zone(s);return z?z.servedRecords||z.records||[]:[];};
  function healthOK(s){const h=(s.account.healthChecks||[]).find(h=>h.id===HC),c=h&&h.config;return !!c&&Object.entries(config()).every(([k,v])=>c[k]===v)&&!c.Disabled&&!c.Inverted&&h.observedHealthy===false&&(s.account.healthChecks||[]).length===1;}
  function preserved(s){const z=zone(s),b=(s.account.buckets||[]).find(b=>b.name==='shop-assets');return !!z&&z.name==='shopkaro.in.'&&z.callerReference==='shop-original'&&!z.private&&(s.account.hostedZones||[]).length===1&&contains(served(s),seed().hostedZones[0].records.slice(0,2))&&!!b&&!b.public&&b.encryption&&(s.account.elbs||[]).some(l=>l.id==='alb-shop'&&l.dns===ALB&&l.canonicalHostedZoneId===ALB_ZONE)&&(s.account.dnsAliases||[]).some(a=>a.dnsName===ALB&&a.hostedZoneId===ALB_ZONE&&a.healthy);}
  const SOLUTION=['aws route53 create-health-check --caller-reference shop-primary-v1 --health-check-config file://primary-health.json','aws route53 change-resource-record-sets --hosted-zone-id ZSHOP --change-batch file://apex-alias.json','aws route53 change-resource-record-sets --hosted-zone-id ZSHOP --change-batch file://weighted-90-10.json','aws route53 change-resource-record-sets --hosted-zone-id ZSHOP --change-batch file://failover-health.json','aws route53 wait resource-record-sets-changed --id /change/C000000003'];
  function budget(k){const ttl=[30,60,120,300,900,3600,86400][k.ttl],detect=k.interval*k.threshold+10,switchSeconds=detect+ttl+20,queries=k.queries*60/ttl,cost=0.50+queries*0.40+0.75+(k.interval===10?2:0);return {ttl,detect,switchSeconds,queries,cost,ok:k.queries>=10&&switchSeconds<=180&&cost<=6};}
  function Q(q,correct,wrong,answer,explain,domain){const choices=wrong.slice();choices.splice(answer,0,correct);return {q,choices,answer,explain,domain};}
  AG.registerLevels('intermediate',[{
    id:'route53',icon:'📡',title:'Route 53 — DNS answer, canary aur failover ka delay',badge:'DNS Daanish',
    hook:{when:'ShopKaro · public launch · fictional course story',title:'"Domain kharid liya. Apex CNAME reject kyun hua?"',text:'Ravi ne shopkaro.in kharida aur root name par ALB hostname ka CNAME banaya. API ne request reject ki. Priya checkout v2 ko small canary dena chahti hai; Neha ko DB migration ke waqt maintenance page chahiye. DNS request split, browser traffic aur data readiness teen alag controls hain. Guwahati ke cold resolver ka first lookup click karke dekho.'},
    objectives:['<b>Name resolution</b>: delegation, public/private zone aur TTL ko trace karo','<b>Record choice</b>: apex Alias vs CNAME aur ALB target metadata choose karo','<b>Eight policies</b>: request context se policy choose karo; exact user split assume mat karo','<b>Recovery</b>: health detection, resolver caches aur app/data readiness separate rakho','<b>Hands-on</b>: real ChangeBatch JSON, health check, propagation waiter aur answer inspect karo','<b>Lab evidence</b>: saved metadata ko actual DNS/probe success se distinguish karo'],
    steps:[
      {q:'Browser ko naam se IP kaise milti hai; TTL kya remember karata hai?',analogy:'Phone directory mein first office doosre office ka number deta hai. Final phone number milne par caller number kuch time save karta hai; saved number har call par directory se refresh nahi hota.',body:'<pre>Cold recursive resolver\n → root: .in nameservers?\n → .in: shopkaro.in nameservers?\n → Route 53 authoritative zone\n → Alias A answer → ALB IPs\n → browser connects to ALB</pre>',points:['Browser/OS/stub recursive resolver ko query bhejta hai. Root/TLD usually referrals dete hain; Route 53 authoritative answer deta hai. Warm caches lookup chain ke steps skip kar sakte hain.','TTL seconds mein positive DNS answer ka cache lifetime guide karta hai. TTL=3600 seconds means a fresh cache may keep old answer about 1 hour; lowering TTL now does not erase answers already cached with old TTL.','DNS TCP/UDP port53 use karta hai; encrypted DNS transports bhi exist karte hain. DNS answer HTTP proxy ya open connection migration nahi.'],asli:'Action: dry run ka Agla step click karo. Resolver → root → .in → Route 53 labels dekho; ALB connection DNS referrals ke baad start hota hai.'},
      {q:'Domain registration aur hosted zone same cheez kyun nahi?',analogy:'Shop ka naam register karna aur public directory entry publish karna separate jobs hain. Staff-only directory sirf authorized office network mein visible hoti hai.',body:'<div class="tbl-wrap"><table><tr><th>Object</th><th>Job</th><th>Debug evidence</th></tr><tr><td>Registrar / parent delegation</td><td>Domain ownership + authoritative NS referral</td><td>Registrar NS matches public zone delegation set</td></tr><tr><td>Public hosted zone</td><td>Internet authoritative records</td><td>NS, SOA, A/AAAA/Alias and record policy</td></tr><tr><td>Private hosted zone</td><td>Associated VPC/private resolver namespace</td><td>VPC associations + DNS settings + Resolver path</td></tr></table></div>',points:['Hosted zone create karna domain buy karna nahi. Registrar elsewhere ho sakta hai; parent NS delegation correct Route 53 zone tak point karni chahiye.','NS authoritative nameservers identify karta hai. SOA zone authority/admin and DNS timing metadata deta hai. Public zone ke default NS/SOA records ko cleanup shortcut se delete mat karo.','Same domain ki multiple public zones possible hain. Wrong zone edit karne par API success ke bawajood public clients old delegated zone ka answer lenge.'],asli:'Action: lab setup ke baad list-resource-record-sets run karo. New zone mein NS/SOA dikhenge; .test domain internet delegation create nahi karta.'},
      {q:'ALB ke liye Alias A kyun; CNAME aur ordinary A mein difference?',analogy:'Directory ki normal entry fixed phone number rakhti hai. CNAME doosri directory name ka referral hai. Route 53 Alias selected supported service se final number ka answer manage karta hai.',body:'<div class="tbl-wrap"><table><tr><th>Choice</th><th>Value / apex</th><th>Kab use karein</th></tr><tr><td>A / AAAA</td><td>IPv4 / IPv6 address</td><td>Known stable IP; hostname A Value mein invalid</td></tr><tr><td>CNAME</td><td>DNS name; no zone apex</td><td>Subdomain → external hostname; same name has no other record types</td></tr><tr><td>Route 53 Alias A/AAAA</td><td>Supported target DNSName + HostedZoneId; apex allowed</td><td>ALB, CloudFront, eligible AWS targets; target capabilities verify karo</td></tr><tr><td>MX / TXT</td><td>Mail route / text metadata</td><td>Email and verification; app traffic routing policy ka substitute nahi</td></tr></table></div>',points:['Alias Route 53 extension hai, CNAME ka alternate spelling nahi. Alias JSON mein AliasTarget hota hai; ordinary ResourceRecords/TTL omit karo. Alias TTL target rules se inherit hota hai; ALB Alias uses ALB 60-second TTL.','ALB DNSName aur CanonicalHostedZoneId describe-load-balancers se read karo. Target hosted-zone ID shopkaro.in zone ID se alag hai. ALB node IP hard-code mat karo.','EvaluateTargetHealth supported target ki health inherit karta hai. ALB target-group health matters; CloudFront alias EvaluateTargetHealth=true supported nahi. Alias automatic application/data recovery guarantee nahi.','Alias arbitrary outside-AWS hostname point nahi karta. Eligible ELB/CloudFront/S3 website alias queries free ho sakti hain; all DNS queries or all Alias targets free assume mat karo.'],asli:'Action: mission mein cat apex-alias.json type karo. AliasTarget ke three fields dekho; TTL/ResourceRecords absent expect karo. S3 website HTTP-only endpoint ke saamne HTTPS chahiye toh CloudFront design next level mein aayega.'},
      {q:'Eight routing policies mein kaunsa decision signal matter karta hai?',analogy:'Directory operator kabhi fixed desk, kabhi capacity lottery, kabhi standby desk choose karta hai. Speed, geography aur percent lottery same question nahi.',body:'<div class="tbl-wrap"><table><tr><th>Policy</th><th>Kab use karein</th><th>Kab nahi / boundary</th></tr><tr><td>Simple</td><td>Single resource; one set can have multiple values</td><td>No attached record health check; no failover policy</td></tr><tr><td>Weighted</td><td>90/10 DNS-query canary; weights 0–255</td><td>Not exact 10% users/HTTP requests; caches aggregate traffic</td></tr><tr><td>Latency</td><td>Lowest measured latency among configured AWS Regions</td><td>Not nearest geography or legal residency control</td></tr><tr><td>Failover</td><td>Active-passive primary/secondary with health</td><td>Not active-active request balancing</td></tr><tr><td>Geolocation</td><td>Approx user country/continent/US state content rules</td><td>Default record needed; DNS alone cannot enforce data compliance</td></tr><tr><td>Geoproximity</td><td>User/resource geography + bias expands/shrinks catchment</td><td>Not latency+bias; available directly without Traffic Flow since Jan 2024</td></tr><tr><td>Multivalue</td><td>Up to 8 healthy record answers, client chooses</td><td>No sessions, connection drain or L7 load balancer guarantee</td></tr><tr><td>IP-based</td><td>Known client/resolver CIDR collections → chosen endpoint</td><td>Not country inference; verify source/ECS visibility</td></tr></table></div>',points:['DNS often sees recursive resolver IP; EDNS Client Subnet can improve location estimates. Geography is approximate; app authorization and data placement controls remain necessary.','Weight 0 normally excludes record while positive-weight records healthy hain. Positive-weight records all unhealthy hon toh healthy zero-weight fallback considered hota hai. All weights0 → equal probability, traffic shutdown nahi.','Company-scale decision example: ShopKaro ke 10 million monthly authoritative queries ko 90/10 weights do. One busy corporate resolver ka cached answer many shoppers share kar sakte hain; per-user experiment needs app/session assignment. ShopKaro is fictional, metric is a workload assumption.'],asli:'Action: policy matching game solve karo. Interview follow-up: closest city vs lowest network latency ka evidence kya hoga? Latency policy uses AWS latency measurements, not just distance.'},
      {q:'Health check kaunsi failure observe karta hai; default kya hai?',analogy:'Guard gate par readiness bell bajata hai. Multiple guards ke reports combine hote hain; ek guard ki stopwatch global decision ka exact SLA nahi.',body:'<p>Endpoint check HTTP/HTTPS/TCP observe karta hai. HTTP/HTTPS healthy response status 200–399 hai. Default request interval <b>30 seconds per checker</b>, default failure threshold <b>3 consecutive checks</b>; optional fast interval <b>10 seconds</b> extra charge laata hai.</p>',points:['Many distributed checkers independently probe karte hain. Endpoint har30 seconds total sirf one request receive karega, aisa assume mat karo. Threshold×interval rough budgeting input hai, real guaranteed global detection bound nahi.','Readiness path /ready dependency condition represent kare. Always-200 page DB write failure hide kar sakta hai. Check named endpoint ko monitor kare; same failover name resolve karke circular check mat banao.','Calculated health check child checks aggregate karta hai. Private resource ko public checker direct private IP se probe nahi kar sakta; CloudWatch-alarm-based check supported metric/alarm state observe kar sakta hai, often custom metric needed.','Ordinary failover primary without HealthCheckId is considered healthy. Alias EvaluateTargetHealth target health inherit kar sakta hai; separate endpoint health check har Alias ke liye mandatory nahi. Disabled check treated healthy; inverted check health flip karta hai. AWS associated health check delete allow karta hai, par stale HealthCheckId ka future routing status unpredictable hai; association repair/cleanup zaroor karo.'],asli:'Action: triage mein primary record inspect karo. HealthCheckId missing aur non-alias primary ho toh dead endpoint DNS se remove hone ka signal absent hai.'},
      {q:'Primary down hua: sab clients immediately backup kyun nahi lenge?',analogy:'Directory change announce ho gaya, par callers ke saved old numbers aur existing calls abhi chal rahe hain. Backup desk par customer ledger ready hona bhi zaroori hai.',body:'<pre>Recovery budget (teaching estimate):\nhealth decision + remaining DNS TTL\n+ client/application retry/cache allowance\n+ backend/data readiness if not already ready</pre>',points:['TTL 3600 seconds lower karne ke baad already cached old answer 1 hour tak remain kar sakta hai. Migration se pehle TTL lower karo, old cache window wait karo, then switch. Application caches/long-lived connections DNS TTL se beyond behavior dikha sakte hain.','Route 53 get-change INSYNC means authoritative Route 53 servers updated. INSYNC recursive cache purge ya client connected/DB recovered proof nahi.','Failover policy healthy primary choose karti hai; primary unhealthy aur secondary healthy ho toh secondary. Dono unhealthy hon toh primary answer return ho sakta hai: fail-open behavior samjho, DNS shutdown assume mat karo.','DNS data replicate nahi karta. DB replication lag RPO affect karta hai; backup app capacity, credentials, session state and writable DB readiness actual RTO affect karte hain. Maintenance read-only message can reduce confusion; successful checkout recovery alag goal hai.'],example:'<div class="war-story"><b>Production me kya hota hai:</b> Old TTL ke resolvers failed primary use karte rehte hain; new answers backup tak jaate hain. Split traffic window mein duplicate writes/retries data consistency break kar sakte hain. Application idempotency and failover runbook test karo.</div>',asli:'Action: flowlab mein TTL 3600 se TTL 60 choose karo. Displayed switch estimate drops; model assumptions ko actual guaranteed maximum mat bolo.'},
      {q:'Office private zone resolve kaise karega; public fallback automatic hai?',analogy:'Staff-only directory office network se accessible hai. Remote branch ko approved directory gateway chahiye; missing staff entry automatically public directory se fill nahi hoti.',body:'<p>Private hosted zone associated VPCs ko namespace deta hai. VPC DNS support/hostnames enable rakho. On-premises se private zone resolve karne ke liye network path + <b>Resolver inbound endpoint</b> and DNS forwarding configure karo. VPC → on-premises names ke liye outbound endpoint + forwarding rule use hota hai; deeper build Advanced networking level mein aayega.</p>',points:['Same name public/private zones split-horizon design bana sakti hain. Associated VPC mein most-specific matching private zone wins; missing record par NXDOMAIN mil sakta hai, public fallback automatic nahi.','Resolver endpoints have ENIs, routing/security and per-hour/query charges; ordinary private zone association ka cost model endpoint hourly cost se alag hai.','Galti jo sab karte hain: office DNS server par private Route 53 zone ID paste karke resolution expect karna. Zone ID DNS server IP nahi; inbound endpoint IP + forwarding/network path needs.'],asli:'Current Route 53 mission public zone model hai. Private DNS packet forwarding, office VPN and runtime resolver cache lab10 mein execute nahi hote.'},
      {q:'TTL aur policy choose karte waqt bill kaunsa count use karega?',analogy:'Directory counter har visitor nahi, counter par aaye lookup requests count karta hai. Cached number se repeat calls counter ko touch nahi karte.',body:'<div class="tbl-wrap"><table><tr><th>Approx public list price, US/commercial 2025–26</th><th>Unit</th></tr><tr><td>First 25 hosted zones</td><td>$0.50/zone/month ≈ ₹44</td></tr><tr><td>Standard queries; first 1 billion/month</td><td>$0.40/million ≈ ₹35.20</td></tr><tr><td>Latency / geography queries</td><td>$0.60 / $0.70 per million ≈ ₹52.80 / ₹61.60</td></tr><tr><td>IP-based queries</td><td>$0.80/million ≈ ₹70.40</td></tr><tr><td>Basic non-AWS endpoint health check</td><td>$0.75/check/month ≈ ₹66</td></tr><tr><td>Fast10s optional non-AWS feature</td><td>+$2.00/check/month ≈ ₹176</td></tr></table></div>',points:['₹88=$1 is course conversion. Taxes, domain registration, Resolver endpoints, target resources and optional features extra. Query price tier/policy and current pricing verify karo.','Basic AWS-endpoint check list price approx $0.50/check/month; up to 50 eligible same/linked-account AWS endpoint checks offer can be free. Non-AWS example deliberately uses $0.75/month and no free allowance.','Flowlab assumes fixed demand of10 million authoritative queries/month at TTL 60 seconds; toy cache rule queries ∝60/TTL. Real query volume depends on cache topology, traffic and record mix; TTL alone cannot predict a production bill.'],asli:'Action: set TTL 60, interval 30, threshold 3, demand 10 million/month. Teaching budget: detection 100 seconds + TTL 60 + client20 =180 seconds; approx $0.50+$4+$0.75=$5.25/month (₹462). Real delay is not bounded by the toy estimate.'},
    ],
    myth:[{myth:'CNAME aur Alias same hain; apex CNAME ALB hostname le lega.',sach:'Apex CNAME invalid hai. Supported ALB target ke liye Alias A/AAAA with target zone metadata use karo; A Value must be an IP.'},{myth:'Weight 10 means exactly 10% users; weight0 kills all traffic.',sach:'Weights authoritative DNS-answer proportions guide karte hain. Caches/user cohorts differ; all-zero weights equal probability, unhealthy positive pool zero-weight fallback consider kar sakta hai.'},{myth:'Primary record present + secondary record present = instant automatic DR.',sach:'Health association/inherited health, detection, old TTL, app retry and data/capacity readiness needed. INSYNC client cache flush nahi.'},{myth:'Geoproximity = latency+bias, Traffic Flow mandatory.',sach:'Geoproximity geographic distance+bias hai; direct records available since Jan 2024. Latency policy different measured-performance decision hai.'}],
    playbook:{title:'Kab use karein / kab nahi — DNS routing decision',use:['DNS-level active-passive endpoint selection with tested cache/recovery budget','Weighted gradual endpoint rollout; actual HTTP/user experiment separately measure','Supported AWS apex target or private/hybrid namespace with explicit delegation'],avoid:['Instant per-request control, sticky cohorts, connection drain or guaranteed global switch deadline','DNS geolocation alone as data residency/security enforcement','Database replication or backup recovery replacement'],how:['Registrar delegation/zone + exact name/type identify karo','Apex? supported Alias; external subdomain? CNAME; stableIP? A/AAAA','Percent? weighted; measured speed? latency; standby? failover; geography? geolocation/geoproximity; knownCIDR? IP-based','Inspect health link, pending changes, old TTL and actual app/data readiness','Apply atomic JSON; wait authoritative INSYNC; inspect answer and test real clients where authorized'],redflags:['ALB hostname in A Value; apex CNAME','Ordinary primary without HealthCheckId; disabled/inverted check hides failure','TTL 3600 during planned quick cutover; exact10% user promise','Private zone missing record; unsafe public fallback assumption'],rule:'Decision tree: one resource → simple; canary → weighted; active-passive → failover; fastest region → latency; country → geolocation; distance+bias → geoproximity; knownCIDRs → IP-based; several healthy IP answers → multivalue.'},
    exam:[{cue:'"zone apex points to ALB"',pick:'Alias A/AAAA to supported target',why:'Apex CNAME disallowed; target HostedZoneId differs from zone ID.'},{cue:'"canary endpoint receives about 10% DNS answers"',pick:'Weighted90/10',why:'Not a guarantee about users/requests or shared resolver cohorts.'},{cue:'"best measured regional performance"',pick:'Latency routing',why:'AWS latency data, not simply shortest geographic distance.'},{cue:'"country/continent-specific DNS answer"',pick:'Geolocation + default record',why:'Approx geography; app/data compliance controls still required.'},{cue:'"resource location plus adjustable bias"',pick:'Geoproximity',why:'Geography catchment, direct records supported without Traffic Flow.'},{cue:'"active-passive DR"',pick:'Failover + health + cache/data runbook',why:'Ordinary primary without check stays healthy; Alias inheritance differs.'},{cue:'"return several healthy IP records"',pick:'Multivalue, up to 8',why:'Not full load-balancer functionality.'},{cue:'"known client CIDR ranges"',pick:'IP-based routing',why:'Configured CIDR collection, not inferred country mapping.'},{cue:'"on-prem resolves private hosted zone"',pick:'Resolver inbound endpoint + forwarding/path',why:'Private endpoint checks can use supported CloudWatch alarm state instead of public probing.'}],
    stages:[
      {type:'dryrun',title:'🔍 Guwahati resolver se canary aur maintenance tak',goal:'Agla step click karo: cold referral chain, Alias answer, weighted selection aur stale cache. Two decisions answer karo.',nodes:[N('user',110,70,{label:'Guwahati'}),N('r53#resolver',370,70,{label:'Recursive resolver'}),N('internet#root',650,70,{label:'Root → .in'}),N('r53',370,245,{label:'Route 53 zone'}),N('alb',780,245,{label:'ALB / apex Alias'}),N('ec2#v1',120,420,{label:'checkout v1 / 90'}),N('ec2#v2',430,420,{label:'checkout v2 / 10'}),N('cf',790,420,{label:'Maintenance CDN'})],edges:[{from:'user',to:'r53#resolver'},{from:'r53#resolver',to:'internet#root'},{from:'r53#resolver',to:'r53'},{from:'r53',to:'alb'},{from:'r53',to:'ec2#v1'},{from:'r53',to:'ec2#v2'},{from:'r53',to:'cf'}],panels:[{id:'answer',title:'Authoritative answer'},{id:'cache',title:'Resolver / application boundary'}],steps:[
        {clock:'cold lookup',say:'Browser recursive resolver ko shopkaro.in puchta hai. Cold resolver root aur .in se referrals leta hai, then delegated Route 53 nameservers query karta hai. Referrals IP request ko app proxy nahi karte.',flows:[{from:'user',to:'r53#resolver',tone:'ok'},{from:'r53#resolver',to:'internet#root',label:'NS referrals',tone:'ok'},{from:'r53#resolver',to:'r53',label:'A query',tone:'ok'}],panels:{answer:['Parent delegation identifies correct public zone'],cache:['Warm cache can skip root/TLD lookup']}},
        {clock:'apex Alias',say:'Zone apex Alias A ALB ki current IPs ka answer return karta hai. ALB hostname ordinary A Value mein invalid hai. Browser IP milne par ALB se connection start karta hai.',flows:[{from:'r53',to:'alb',label:'Alias A answer',tone:'ok'}],panels:{answer:['AliasTarget: DNSName + target HostedZoneId','ALB TTL rules; no custom Alias TTL'],cache:['DNS does not proxy checkout requests']},ask:{q:'Ravi shopkaro.in apex ko ALB hostname par point kare. Valid record?',choices:['Alias A with ALB DNSName and canonical target zone ID','CNAME at apex with a shorter TTL and no other settings','Ordinary A ResourceRecords Value containing ALB DNSName','NS record containing ALB DNSName instead of nameservers'],answer:0,explain:'Supported Alias works at apex. CNAME apex conflicts with required NS/SOA; A requires IP; NS delegates to DNS servers, not ALB.'}},
        {clock:'90 / 10',say:'checkout.shopkaro.in ki weighted records v1=90/v2=10 hain. Authoritative selection approximately90/10 DNS queries distribute karti hai; one resolver cached answer many HTTP shoppers share kar sakte hain.',flows:[{from:'r53',to:'ec2#v1',label:'weight90',tone:'ok'},{from:'r53',to:'ec2#v2',label:'weight10',tone:'slow'}],panels:{answer:['Relative weights; no fixed shopper allocation'],cache:['Session-level experiment needs app assignment']}},
        {clock:'primary unhealthy',say:'Readiness checks primary unavailable report karte hain. Failover group secondary maintenance answer choose karti hai for fresh authoritative lookups. Maintenance CloudFront/S3 design upcoming CDN level mein build hoga; current CLI fixture uses documentation IPs.',flows:[{from:'r53',to:'cf',label:'fresh answer',tone:'ok'}],panels:{answer:['Primary check/inherited health association required'],cache:['Existing primary connections are not moved']}},
        {clock:'old cache',say:'Resolver ne failure se just pehle TTL 3600 seconds ke saath primary answer save kiya. Lower TTL after failure old cached answer clear nahi karta; application cache/connection lifetime extra delay de sakti hai.',panels:{cache:['Old remaining TTL may approach1 hour','No universal guaranteed client switch bound']},ask:{q:'TTL 3600 tha. Fresh secondary answer ke baad sab clients kab switch?',choices:['No exact guarantee; old cache may retain primary about1 hour, app behavior can add delay','Exactly30 seconds because health interval flushes all recursive DNS caches','Immediately after INSYNC because Route 53 clears browser connection pools','Exactly10% per minute because weighted canary controls failover cache expiry'],answer:0,explain:'TTL guides DNS cache lifetime; check interval and INSYNC do not flush client caches. Weighted proportions have no cache-expiry role; application behavior adds uncertainty.'}},
        {clock:'runbook',say:'Planned migration: lower TTL in advance, wait prior cache window, verify standby app/data readiness, then cut over and observe clients. DNS recovery budget aur data RPO ko separate measurements do.',panels:{answer:['Waiter: authoritative configuration synchronized'],cache:['App retry/idempotency and replica lag still matter']}},
      ],lesson:'DNS chooses answers at lookup time. Alias target, relative weights, health and existing caches jointly affect traffic; no instant global application failover promise.'},
      {type:'flowlab',title:'🎛️ Cache budget — recovery aur query bill',goal:'Fixed demand at least 10 million/month (TTL 60 reference), modeled client switch ≤180 seconds, approximate monthly DNS/check subtotal ≤$6. Demand reduce karke win nahi milegi.',scenario:'Teaching estimate, not an AWS worst-case guarantee: detection = interval × threshold + 10 seconds aggregation allowance; switch = detection + TTL + 20 seconds client allowance. Real distributed checking, caches and connections can take longer. Query toy rule = reference demand × 60 / TTL; no universal traffic law. One public zone + non-AWS HTTP check, standard queries, ₹88/$1; AWS targets/data/Resolver/taxes extra.',knobs:[{id:'ttl',label:'TTL choice',min:0,max:6,step:1,value:5,labels:{0:'30 seconds',1:'60 seconds',2:'120 seconds',3:'300 seconds',4:'900 seconds',5:'3600 seconds',6:'86400 seconds'}},{id:'interval',label:'Per-checker interval',min:10,max:30,step:20,value:30,unit:' seconds'},{id:'threshold',label:'Consecutive failures',min:1,max:10,step:1,value:3,unit:' checks'},{id:'queries',label:'Query demand',min:1,max:10,step:1,value:10,unit:' M/month'}],model:k=>{const b=budget(k);return {readouts:[{label:'Modeled detection budget',value:b.detect+' seconds',tone:'info'},{label:'Modeled client switch',value:b.switchSeconds+' seconds',tone:b.switchSeconds<=180?'ok':'bad'},{label:'Estimated authoritative queries',value:b.queries.toFixed(3)+' million/month',tone:'info'},{label:'Approx DNS/check subtotal',value:'$'+b.cost.toFixed(2)+'/month · ₹'+Math.round(b.cost*88),tone:b.cost<=6?'ok':'bad'},{label:'Demand preserved?',value:k.queries>=10?'10 million/month reference kept':'Demand below fixed workload',tone:k.queries>=10?'ok':'bad'}],verdict:{ok:b.ok,text:b.ok?'Teaching budget passes. Measure actual resolver/client behavior and complete target costs before a real migration.':'Example: TTL 60 seconds, interval 30 seconds, threshold 3, demand 10 million/month →180 seconds and approx $5.25/month.'}};},check:k=>budget(k).ok,lesson:'TTL 60 / interval 30 / threshold 3 / demand 10 million → detection 100 seconds + TTL 60 + allowance 20 =180 seconds; approx $5.25/month. Fast 10 seconds raises non-AWS check fee by approx $2/month. Neither calculation guarantees actual end-user recovery.'},
      {type:'match',title:'🧩 Requirement → routing signal',instructions:'Har use case ko distinct policy se jodo. DNS policy application guarantees replace nahi karti.',pairs:[{left:'Single ALB, no policy health check needed',right:'Simple',explain:'One logical endpoint; Alias can inherit supported target health.'},{left:'New endpoint about 10% DNS answers',right:'Weighted',explain:'Relative DNS weights; user/request experiment needs separate control.'},{left:'Lowest measured regional network latency',right:'Latency',explain:'AWS measurement, geographic distance alone nahi.'},{left:'Primary unhealthy → standby',right:'Failover',explain:'Health association and client/cache/data budget required.'},{left:'Country/continent content localization',right:'Geolocation',explain:'Approx source location; add default; not standalone legal enforcement.'},{left:'Geographic catchment expand using bias',right:'Geoproximity',explain:'User/resource locations and bias; not latency+bias.'},{left:'Up to 8 healthy record answers',right:'Multivalue',explain:'DNS-level spread; no full L7 load-balancer semantics.'},{left:'Known customer CIDR → endpoint mapping',right:'IP-based',explain:'CIDR collection and source/ECS visibility, not inferred country.'}]},
      {type:'bins',title:'🗂️ Alias / CNAME / dono / koi nahi',instructions:'Alias and CNAME ki stated capability compare karo; actual record target support still verify karo.',bins:[{id:'alias',label:'Alias only'},{id:'cname',label:'CNAME only'},{id:'both',label:'Dono possible'},{id:'neither',label:'Koi nahi'}],items:[{text:'Zone apex shopkaro.in → supported ALB DNS target',bin:'alias',explain:'Apex Alias valid; apex CNAME disallowed.'},{text:'news.shopkaro.in → arbitrary third-party hostname, no other records',bin:'cname',explain:'CNAME supports external names; Alias arbitrary external hostname accept nahi karta.'},{text:'app.shopkaro.in → supported ALB hostname, no other records',bin:'both',explain:'Subdomain CNAME possible; Alias A often avoids extra DNS lookup/eligible query charge.'},{text:'Eligible ALB target answer with no Route53 Alias query charge',bin:'alias',explain:'Free eligible Alias queries; CNAME query chain can incur query charges.'},{text:'Apex → supported same-name S3 website endpoint',bin:'alias',explain:'Alias target supported; S3 website HTTP-only and bucket-name rules matter.'},{text:'Put arbitrary IPv4 address into AliasTarget DNSName or CNAME',bin:'neither',explain:'Stable IPv4 belongs in ordinary A ResourceRecords, not hostname/target fields.'}]},
      {type:'triage',title:'🩺 Primary down, DNS still primary',symptom:'status.shopkaro.in has a non-alias failover pair. Primary HTTP fixture down for several check windows; fresh authoritative query still returns203.0.113.10. Find the missing signal.',commands:[{cmd:'aws route53 list-resource-record-sets --hosted-zone-id ZSHOP',out:'{"ResourceRecordSets":[{"Name":"status.shopkaro.in.","Type":"A","SetIdentifier":"primary","Failover":"PRIMARY","TTL":60,"ResourceRecords":[{"Value":"203.0.113.10"}]},{"Name":"status.shopkaro.in.","Type":"A","SetIdentifier":"maintenance","Failover":"SECONDARY","TTL":60,"ResourceRecords":[{"Value":"203.0.113.20"}]}]}',clue:true,note:'Ordinary primary has no HealthCheckId and no AliasTarget inheritance. Route53 considers primary healthy.'},{cmd:'aws route53 list-health-checks',out:'{"HealthChecks":[]}',clue:true,note:'No endpoint check exists; creating check alone also needs association to record.'},{cmd:'aws route53 test-dns-answer --hosted-zone-id ZSHOP --record-name status.shopkaro.in --record-type A',out:'{"RecordData":["203.0.113.10"],"ResponseCode":"NOERROR"}',clue:false,note:'Fresh authoritative model answer, not recursive stale-cache evidence.'},{cmd:'aws route53 get-change --id /change/C000000001',out:'{"ChangeInfo":{"Id":"/change/C000000001","Status":"INSYNC"}}',clue:false,note:'Published configuration lacks health association; synchronized wrong config remains wrong.'}],questions:[Q('Strongest explanation for fresh primary answer?','Non-alias primary has no health association, so DNS treats primary as healthy',['Secondary IPv4 address requires matching primary address before DNS can fail over','TTL 60 expires too quickly for any authoritative server to select secondary','INSYNC forces primary answers until an operator deletes the public hosted zone'],0,'Missing HealthCheckId leaves ordinary primary healthy. Secondary should differ; TTL affects caches rather than attaching health; INSYNC publishes configuration and deleting the zone destroys DNS.','resilient'),Q('Repair preserving active-passive routing?','Create readiness check, link primary HealthCheckId, then verify authoritative answer',['Lower primary TTL without attaching health because cache expiry invents health state','Change weighted v2 to100 and assume a different record name repairs the failover pair','Remove NS and SOA records so parent delegation automatically selects standby IPv4'],1,'Check plus association supplies failure signal. TTL alone cannot infer health; checkout weights affect another name; deleting NS/SOA breaks authority rather than creating failover.','resilient')]},
      (function(){const tasks=[{text:'Apex serving Alias A points to original ALB target with inherited health',check:s=>contains(served(s),[apex()])},{text:'Serving checkout records v1=90/v2=10, TTL 60, original two endpoints',check:s=>contains(served(s),weighted())},{text:'Enabled non-inverted /ready HTTP primary check has correct endpoint, interval 30 and threshold 3',check:healthOK},{text:'Serving status primary links check; secondary maintenance; TTL 60; unhealthy primary resolves secondary',check:s=>contains(served(s),failover())&&!!zone(s)&&eq(AG.dnsAnswer(s.account,zone(s),'status.shopkaro.in','A'),['203.0.113.20'])},{text:'Authoritative changes INSYNC; only7 planned records; original zone, NS/SOA, ALB and private assets preserved',check:s=>preserved(s)&&served(s).length===7&&(s.account.dnsChanges||[]).length>0&&(s.account.dnsChanges||[]).every(c=>c.Status==='INSYNC')}];return {type:'terminal',title:'🖥️ Mission — correct records, health aur propagation',instructions:'ls se four JSON files dekho; cat filename se contents read karo. First health check ID 00000000-0000-4000-8000-000000000001; three changes C000000001/2/3. Later waiter previous changes in same zone also publishes. Five intended actions; no fake apply command.',goal:'Existing ZSHOP/ shopkaro.in preserve karo. Apex Alias A → original ALB, checkout v1/v2 weights90/10 TTL 60, status failover primary /ready HTTP check + maintenance secondary TTL 60. Fixture primary203.0.113.10 down hai; fixture secondary203.0.113.20 healthy. All edits authoritative INSYNC hon. JSON files ready hain; target metadata lab fixture hai. No real probes, recursive cache or elapsed propagation time simulated.',account:seed(),files:{'primary-health.json':file(config()),'apex-alias.json':file(batch([apex()])),'weighted-90-10.json':file(batch(weighted())),'failover-health.json':file(batch(failover()))},tasks,success:AG.allOf(tasks),solution:SOLUTION.slice(),hints:[SOLUTION[0]+' — nudge: primary readiness signal pehle create karo; cat primary-health.json read karo',SOLUTION[1]+' — apex uses AliasTarget, not ALB hostname as A Value',SOLUTION[2]+' — same name/type pair, unique SetIdentifier and equal TTL 60',SOLUTION[3]+' — primary HealthCheckId must link created check; secondary no-check fixture considered healthy',SOLUTION[4]+' — final C000000003 waiter publishes previous zone changes too; get-change alone just inspects pending state in this teaching model'],successText:'Authoritative serving snapshot repaired. Serving-state answer check: status.shopkaro.in →203.0.113.20. A read-only test-dns-answer before the final waiter shows the old serving snapshot; terminal locks after completion. DNS-answer model uses fixture health; real DNS caches, ALB readiness and client/data recovery remain separate tests.'};})(),
      {type:'docker',title:'🐳 Lab10 — actual Route53 API metadata',project:'10-route53-routing',goal:'README ex1–ex5: create scoped ALB/zone → Alias/weighted/failover JSON → remove/repair health association → inspect emulator limits → scoped cleanup.',why:'Real CLI JSON and metadata persistence practice milega. Moto no real DNS/HTTP probes; test-dns-answer currently404, canned health response not endpoint proof.',steps:[{text:'README Setup exports follow karo, then create lab-owned VPC/ALB/public zone.',cmd:'cd aws-gurukul/docker-labs\n./start-moto.sh\nsource env.sh\ncd 10-route53-routing\n# README Setup isolation exports run karo.\nbash setup.sh\nsource .lab/resources.sh',expect:'["NS","SOA"] and ALB canonical zone Z2P70J7EXAMPLE in current Moto.'},{text:'Real CLI health check and JSON ChangeBatch persist karo, then inspect config.',cmd:'bash exercises.sh\nsource .lab/resources.sh',expect:'"INSYNC"; v1 Weight90 / v2 Weight 10; PRIMARY has HealthCheckId; SECONDARY has null Check.'},{text:'Remove primary health association, inspect missing Check, then restore.',cmd:'aws route53 change-resource-record-sets --hosted-zone-id "$ZONE" --change-batch file://.lab/missing-health.json\naws route53 change-resource-record-sets --hosted-zone-id "$ZONE" --change-batch file://.lab/repair.json',expect:'Both edits return ChangeInfo Status=INSYNC in current Moto; README query shows null then restored ID.'},{text:'Optional test-dns-answer shows current emulator404; cleanup confirms only lab resources removed.',cmd:'aws route53 test-dns-answer --hosted-zone-id "$ZONE" --record-name status.shopkaro-lab10.test --record-type A\nbash cleanup.sh',expect:'An error occurred (404) when calling the TestDNSAnswer operation: Not Found. Cleanup: four empty lists.'}],observe:Q('Moto says HTTP200 for documentation IP and test-dns-answer404. What passed?','Saved health/record metadata; actual probe and DNS-answer behavior remain unverified',['Live HTTP readiness test and full public DNS delegation were measured by metadata','A verified application failover within180 seconds and exact10% user distribution','The real AWS service rejects every test-dns-answer call because operation is invalid'],2,'Metadata persisted. Canned HTTP200 for dummy endpoint is not a real probe; no DNS/latency/canary measurement; TestDNSAnswer is valid AWS API but current Moto endpoint failed.','resilient')},
      {type:'quiz',title:'📝 Bonus — DNS decisions under real constraints',questions:[
        Q('shopkaro.in apex must point to ALB without pinning node IPs. Best record?','Alias A with ALB DNSName and ALB canonical hosted-zone ID',['CNAME at shopkaro.in with ALB hostname and custom TTL 60','Ordinary A whose ResourceRecords Value is the ALB hostname','NS whose nameserver value is the ALB endpoint DNS name'],0,'Alias supports eligible apex targets. CNAME apex conflicts with mandatory zone records; ordinary A requires IPv4; NS delegates DNS authority, not HTTP traffic.','high-performing'),
        Q('90/10 weighted DNS canary has35% HTTP requests hitting v2. Why plausible?','Resolver caching and client reuse mean DNS-answer ratios differ from HTTP ratios',['Weight 10 means ten clients per second regardless of resolver queries or TTL','Route53 changes every failed checkout request into a successful v2 request','A standard weighted record automatically assigns stable10% user cohorts'],1,'Weights affect authoritative answers; shared caches/connections skew downstream counts. Weights are relative not requests/second; DNS does not inspect checkout outcomes or assign stable user cohorts.','high-performing'),
        Q('Region geographically closest is slower on network measurements. Pick speed policy?','Latency routing across configured AWS Regions, based on AWS measurement data',['Geoproximity routing with zero bias, which directly measures HTTP response speed','Geolocation routing based on country, which selects the lowest measured latency','Simple routing with two IPs, which ranks every client connection by RTT'],2,'Latency policy uses AWS latency data. Geoproximity measures geography+bias; geolocation maps location; simple multi-values do not measure/rank client RTT.','high-performing'),
        Q('Primary fails; authoritative failover check is unhealthy; some clients still use old IP. Why?','Old resolver cache and existing connections can outlive the authoritative update',['INSYNC causes every recursive resolver to retain primary until zone recreation','Secondary record must share primary IP before cached clients can use failover','Failure threshold automatically copies every database row to standby storage'],3,'Cache TTL and connection/application behavior can delay adoption. INSYNC does not force primary retention or purge; secondary is distinct; health thresholds do not replicate data.','resilient'),
        Q('User/resource geography with adjustable catchment bias; avoid mandatory TrafficFlow. Choice?','Geoproximity records; direct policy support exists without TrafficFlow',['Latency records; geographic bias is a mandatory parameter on latency policy','Weighted records; percent values represent exact geographic catchment radii','Geolocation records; country mappings automatically tune resource distance bias'],0,'Geoproximity supports distance+bias and direct records since Jan 2024. Latency has no geography-bias knob; weights are not geographic radii; geolocation maps regions rather than distance catchments.','high-performing'),
        Q('Private DB readiness cannot be reached by public health checkers. Candidate signal?','Supported CloudWatch-alarm-based health check with a meaningful DB readiness metric',['HTTP endpoint health check directly probing an RFC1918 DB address from the internet','Calculated check with zero child threshold to prove every DB query succeeds','Private hosted-zone Alias that automatically executes authenticated SQL transactions'],1,'Alarm-based health can represent private resource health via supported metrics/alarms. Public checks cannot reach private IPs; zero calculated threshold stays healthy; Alias does not run SQL.','resilient'),
        Q('All weighted records have Weight 0. Expected selection, absent other differences?','Records remain eligible with equal probability; all-zero is not traffic shutdown',['Every authoritative query receives NXDOMAIN until one weight becomes positive','Only lexicographically first SetIdentifier remains eligible to receive all traffic','DNS automatically deletes every zero-weight resource record after one TTL'],2,'Allzero weights are equally likely. Zero does not delete records or imply NXDOMAIN; no first-identifier-only AWS rule. Positive-healthy vs zero fallback is a separate case.','resilient'),
        Q('Office DNS needs associated VPC private zone names. Required direction?','Resolver inbound endpoint plus office forwarding and authorized network path',['Resolver outbound endpoint alone without forwarding or route from office DNS','Public NS delegation to the private hosted-zone ID as if ID were an IP','Public CNAME for every private IP with no private DNS path or permissions'],3,'Inbound accepts queries entering VPC from on-premises. Outbound serves VPC→external direction; zone ID is not a server IP; public CNAME is not an authorized private resolver path.','secure'),
      ]},
    ],
    interview:{title:'🎤 DNS incident review',instructions:'Answer scope, cache behavior and explicit health evidence explain karo. Last task existing metadata repair karti hai.',questions:[
      Q('Non-alias primary failover record has no HealthCheckId. What state does DNS assume?','Primary considered healthy; attach readiness health signal for automatic failure selection',['Primary considered unhealthy because the ordinary record has no AliasTarget field','Both records automatically probed through their DNS name before every lookup','Missing check makes the entire authoritative zone stop returning NS responses'],0,'No associated health check normally means healthy. Ordinary record need not be Alias; no automatic per-query endpoint probe; NS authority remains independent.','resilient'),
      Q('Compliance team asks EU data residency. What does DNS geolocation provide alone?','Approx source-location answer mapping; app authorization and data placement still needed',['Proof that each user is physically in the chosen region during every request','Encryption and database replication policy automatically enforced from a DNS record','A guarantee that VPN users and all recursive resolvers reveal true client location'],1,'Geolocation maps approximate DNS source/ECS location; residency needs broader controls. Physical location may differ, and DNS does not enforce encryption/replication or defeat VPNs.','secure'),
      Q('Both primary and secondary health checks fail. Failover behavior to plan for?','Primary answer can return as fail-open; healthy backup and app recovery still needed',['DNS always removes the whole hosted zone and revokes the domain registration','Every query automatically waits until a real DB restore has completed successfully','Route53 automatically selects unrelated third-region endpoint outside the record set'],2,'Failover can return primary when both unhealthy. DNS does not delete registration, await DB restore or invent an unconfigured third endpoint; test failure runbooks.','resilient'),
      Q('One public zone,10 million standard queries/month, one non-AWS basic HTTP check. Subtotal?','Approx $5.25/month before optional features, targets, registration and taxes',['Approx $4.00/month including unlimited zones, all health checks and target servers','Approx $0.75/month because every ordinary A query to outside AWS is free','Approx $7.25/month because default30 second checks require fast10 second add-on'],3,'Approx $0.50 zone+$4 queries+$0.75 check=$5.25. $4 omits fixed components; ordinary A queries not free; $2 fast add-on applies only when selected for this non-AWS example.','cost-optimized'),
      {terminal:(function(){const a=seed();a.hostedZones[0].records=[...a.hostedZones[0].records.slice(0,2),apex(),...weighted(),...failover().map(r=>{const x={...r,TTL:3600};delete x.HealthCheckId;return x;})];a.healthChecks=[{id:HC,callerReference:'shop-primary-v1',config:{...config(),Inverted:false,Disabled:false},observedHealthy:false,version:1}];const tasks=[{text:'Existing primary check linked; serving pair TTL 60; fixture answer maintenance',check:s=>healthOK(s)&&contains(served(s),failover())&&!!zone(s)&&eq(AG.dnsAnswer(s.account,zone(s),'status.shopkaro.in','A'),['203.0.113.20'])},{text:'Apex/weighted/zone preserved, only planned records and INSYNC edits',check:s=>preserved(s)&&contains(served(s),[apex(),...weighted()])&&served(s).length===7&&(s.account.dnsChanges||[]).length>0&&(s.account.dnsChanges||[]).every(c=>c.Status==='INSYNC')}];const solution=['aws route53 change-resource-record-sets --hosted-zone-id ZSHOP --change-batch file://repair-failover.json','aws route53 wait resource-record-sets-changed --id /change/C000000001'];return {title:'🖥️ Existing health check unused: repair, do not recreate',goal:'Existing primary /ready HTTP check ID00000000-0000-4000-8000-000000000001 is unhealthy. Current status primary has no HealthCheckId and pair TTL 3600. cat repair-failover.json inspect karo; existing record pair update + authoritative waiter. Original apex/canary/assets preserve karo.',account:a,files:{'repair-failover.json':file(batch(failover()))},tasks,success:AG.allOf(tasks),solution,hints:solution.slice(),successText:'Serving failover pair uses existing check and TTL 60; authoritative answer is maintenance documentation IP. Existing client caches still require runtime verification.'};})()},
    ]},
    success:['DNS delegation, authoritative answer aur client cache separate explain kar sakta hoon','Alias/CNAME/apex rules aur eight policy signals choose kar sakta hoon','State-changing JSON repair plus health association/propagation verify kar sakta hoon','DNS failover ko app/data recovery aur emulator metadata se distinguish kar sakta hoon'],
    homework:'<p><b>Optional approved real AWS sandbox only; billable:</b> domain/zone/query/health/ALB/CDN costs estimate karo. A delegated test subdomain use karo; existing production domain overwrite mat karo. Supported ALB Alias target metadata read karo, readiness check and active-passive endpoints review karo. Lower TTL ahead of test, wait old TTL window, then approved endpoint failure inject karke fresh authoritative answers, multiple recursive resolvers and actual app recovery separately measure karo. Data loss/replication lag and retry behavior record karo. Cleanup: exact test records delete, propagated change wait, health checks remove, test-only hosted zone delete, lab-owned ALB/listeners/target groups and other target resources clean karo. Domain auto-renew and registration costs separately review karo. Shared zone NS/SOA or existing records reset mat karo.</p>',
    cards:[{front:'TTL kya control karta hai?',back:'Positive answer cache lifetime guidance in seconds. Lower TTL does not clear already cached old answers; applications/connections may add delay.'},{front:'Apex ALB: Alias vs CNAME?',back:'Supported Alias A/AAAA with target DNSName+HostedZoneId. CNAME cannot be at zone apex; ordinary A Value needs IPv4.'},{front:'Weighted90/10 kis count par?',back:'Relative authoritative DNS answers. Shared caches, traffic volume and connections mean not exact user/HTTP split; all-zero weights equal probability.'},{front:'Latency vs geoproximity?',back:'Latency: AWS measured regional network performance. Geoproximity: user/resource geographic distance+bias; direct policy available without TrafficFlow.'},{front:'Default endpoint check settings?',back:'30 seconds per checker; threshold 3 consecutive checks. Fast 10 seconds optional extra charge; distributed aggregation means no exact global bound.'},{front:'Ordinary primary no HealthCheckId?',back:'Normally considered healthy. Associate correct readiness check; Alias EvaluateTargetHealth can inherit supported target health separately.'},{front:'INSYNC proves what?',back:'Route53 authoritative change propagated. Not recursive cache flush, client connection migration, database replication or application recovery.'},{front:'Private zone from on-premises?',back:'Resolver inbound endpoint, office forwarding and authorized routing/security. Most-specific private zone missing record can give NXDOMAIN, no automatic public fallback.'}],
  }]);
})();
